// N8N-SINTEL-02 FASE 5/6: extrae SOLO los adjuntos .xml de cada correo.
// Un correo puede traer 0, 1 o varios XML (y PDFs que se descartan aqui,
// nunca se interpretan como factura). No parsea el XML -- SINTEL es el
// unico que hace eso (upload-document -> pipeline oficial).
const out = [];
for (const item of $input.all()) {
  const binaryKeys = Object.keys(item.binary || {});
  const xmlKeys = binaryKeys.filter((k) => {
    const bin = item.binary[k];
    const name = (bin.fileName || '').toLowerCase();
    return name.endsWith('.xml') || (bin.mimeType || '').includes('xml');
  });

  if (xmlKeys.length === 0) {
    // Correo sin XML -- FASE 5 exige soportarlo sin romper: se descarta
    // silenciosamente aqui, no llega ningun item a los nodos siguientes.
    continue;
  }

  for (const key of xmlKeys) {
    out.push({
      json: {
        gmail_message_id: item.json.id,
        gmail_subject: item.json.subject,
        gmail_from: item.json.from ? item.json.from.value?.[0]?.address : undefined,
        attachment_filename: item.binary[key].fileName,
        // correlation_id propio de n8n (namespace distinto al event_id de
        // SINTEL, Fase 11 de la mision -- nunca se reusan entre si).
        correlation_id: `${item.json.id}-${item.binary[key].fileName}`,
      },
      binary: { file: item.binary[key] },
    });
  }
}
return out;

